const meta = $('Name PDF').first().json;
const messageId = String(meta.messageId ?? '');

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedMessageIds)) {
  staticData.processedMessageIds = [];
}

if (messageId && !staticData.processedMessageIds.includes(messageId)) {
  staticData.processedMessageIds.push(messageId);
  if (staticData.processedMessageIds.length > 200) {
    staticData.processedMessageIds = staticData.processedMessageIds.slice(-200);
  }
}

return [
  {
    json: {
      status: 'processed',
      filename: meta.filename,
      folder: meta.folder,
      messageId,
    },
  },
];

const meta = $('Build reMarkable HTML').first().json;
const item = $input.first();

item.json = {
  ...item.json,
  title: meta.title,
  filename: meta.filename,
  folder: meta.folder,
  messageId: meta.messageId,
};

if (item.binary?.data) {
  item.binary.data.fileName = meta.filename;
  item.binary.data.mimeType = 'application/pdf';
}

return [item];

const item = $input.first().json;
const subject = String(item.subject ?? '').trim() || 'NZZ Briefing';
const htmlRaw = String(item.textHtml ?? '').trim();
const textPlain = String(item.textPlain ?? '').trim();

if (!htmlRaw && !textPlain) {
  throw new Error(`Empty body for mail: ${subject}`);
}

function berlinDateString(date) {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date);
}

function escapeHtml(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function sanitizeFilename(name) {
  const ascii = name
    .replace(/ß/g, 'ss')
    .replace(/ẞ/g, 'SS')
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/Ä/g, 'Ae')
    .replace(/Ö/g, 'Oe')
    .replace(/Ü/g, 'Ue')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');
  const base =
    ascii
      .replace(/[^A-Za-z0-9._-]+/g, '-')
      .replace(/-+/g, '-')
      .replace(/^[-.]+|[-.]+$/g, '') || 'NZZ-Mail';
  return base.endsWith('.pdf') ? base : `${base}.pdf`;
}

function extractBody(html) {
  const bodyMatch = html.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i);
  return bodyMatch ? bodyMatch[1] : html;
}

function cleanEmailHtml(html) {
  let out = extractBody(html);
  out = out
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<img\b[^>]*(?:width\s*=\s*["']?1["']?|height\s*=\s*["']?1["']?)[^>]*>/gi, '')
    .replace(/<img\b[^>]*height\s*=\s*["']?1["']?[^>]*>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '');

  // Email templates often lazy-load editorial photos via data-src/data-original.
  // Chromium only renders normal src attributes when generating the PDF.
  out = out.replace(/<img\b([^>]*?)>/gi, (tag, attrs) => {
    if (!/\bsrc\s*=/i.test(attrs)) {
      const lazy = attrs.match(/\b(?:data-src|data-original|data-lazy-src)\s*=\s*(["'])(.*?)\1/i);
      if (lazy?.[2]) attrs += ` src="${lazy[2]}"`;
    }
    if (!/\bloading\s*=/i.test(attrs)) attrs += ' loading="eager"';
    return `<img${attrs}>`;
  });

  return out.trim();
}

const received = item.date ? new Date(item.date) : new Date();
const stamp = Number.isNaN(received.getTime())
  ? berlinDateString(new Date())
  : berlinDateString(received);

let bodyInner;
if (htmlRaw) {
  bodyInner = cleanEmailHtml(htmlRaw);
} else {
  bodyInner = textPlain
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean)
    .map((p) => `<p>${escapeHtml(p).replace(/\n/g, '<br />')}</p>`)
    .join('\n');
}

const filename = sanitizeFilename(subject);
const documentHtml = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="utf-8" />
  <title>${escapeHtml(subject)}</title>
  <style>
    @page { margin: 14mm; }
    body {
      margin: 0;
      color: #111;
      font-family: Georgia, "Times New Roman", serif;
      font-size: 12.5pt;
      line-height: 1.45;
    }
    h1 {
      font-size: 22pt;
      line-height: 1.2;
      margin: 0 0 0.4em;
    }
    h2 {
      font-size: 14.5pt;
      line-height: 1.25;
      margin: 1.35em 0 0.45em;
      padding-top: 0.2em;
      border-top: 1px solid #bbb;
    }
    h2:first-of-type { border-top: 0; padding-top: 0; }
    h3 { font-size: 12.5pt; margin: 1em 0 0.35em; }
    p { margin: 0 0 0.75em; }
    ul { margin: 0 0 1em; padding-left: 1.2em; }
    li { margin: 0 0 0.55em; }
    a { color: #111; text-decoration: underline; }
    img { max-width: 100%; height: auto; }
    table { width: 100% !important; max-width: 100% !important; }
    .meta {
      font-family: sans-serif;
      font-size: 9.5pt;
      color: #444;
      margin: 0 0 1.4em;
    }
  </style>
</head>
<body>
  <p class="meta">${escapeHtml(subject)} · ${escapeHtml(stamp)} · Gmail reMarkable inbox</p>
  ${bodyInner}
</body>
</html>`;

const binary = await this.helpers.prepareBinaryData(
  Buffer.from(documentHtml, 'utf8'),
  'index.html',
  'text/html',
);

return [
  {
    json: {
      title: subject,
      filename,
      stamp,
      folder: `/News/${stamp}`,
      messageId: String(item.messageId ?? ''),
      from: String(item.from ?? ''),
    },
    binary: { data: binary },
  },
];

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedMessageIds)) {
  staticData.processedMessageIds = [];
}

const out = [];
for (const item of $input.all()) {
  const meta = item.json.metadata && typeof item.json.metadata === 'object' ? item.json.metadata : {};
  const messageId = String(
    meta['message-id'] ?? meta.messageId ?? item.json.attributes?.uid ?? '',
  );
  if (messageId && staticData.processedMessageIds.includes(messageId)) continue;

  out.push({
    json: {
      ...item.json,
      messageId,
    },
  });
}

return out;
